use localbrain_core::backend::{auto_work, db, references};
use serde_json::{json, Value};
use std::collections::BTreeMap;
#[test]
fn full_inventory_and_codepoint_windows_match_frozen_python() {
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("source.db");
    let connection = rusqlite::Connection::open(&path).unwrap();
    connection.execute_batch(db::SCHEMA).unwrap();
    connection.execute_batch("PRAGMA foreign_keys=OFF").unwrap();
    connection.execute_batch(SQL).unwrap();
    let body = format!(
        "{}A{}\n{}",
        "α".repeat(129),
        "😀".repeat(65537),
        "z".repeat(1000)
    );
    connection.execute("INSERT INTO activity_events(id,session_id,sequence,occurred_at,event_type,role,text,source_line) VALUES ('large',1,1,'2026-11-15T01:00:00.123456+09:00','message','user',?,1)",[body]).unwrap();
    drop(connection);
    let cases: Value = serde_json::from_str(INVENTORY).unwrap();
    for case in cases.as_array().unwrap() {
        let mut emitted = Vec::new();
        let manifest = auto_work::inventory(
            &path,
            case["size"].as_u64().unwrap() as usize,
            |kind, value| {
                emitted.push(json!([kind, value]));
                Ok(())
            },
        )
        .unwrap();
        assert_eq!(manifest, case["manifest"]);
        assert_eq!(
            references::hash_payload(&json!(emitted)),
            case["events_hash"]
        );
    }
}
#[test]
fn ordered_louvain_partitions_match_frozen_synthetic_rings() {
    let cases: Value = serde_json::from_str(GRAPHS).unwrap();
    for (index, case) in cases.as_array().unwrap().iter().enumerate() {
        let vectors = case["vectors"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(key, value)| {
                (
                    key.clone(),
                    value
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|v| v.as_f64().unwrap() as f32)
                        .collect(),
                )
            })
            .collect::<BTreeMap<String, Vec<f32>>>();
        let result = auto_work::graph::group_vectors(&vectors, &case["parameters"]).unwrap();
        assert_eq!(
            result["areas"], case["areas"],
            "case {index} {}",
            case["parameters"]
        );
        assert_eq!(result["engine"]["implementation"], "localbrain-rust");
    }
}
